entries[94521] = { ["name"] = "Breath of the Hydra", ["text"] = "Binds when picked up\nUnique-Equipped: Breath of the Hydra (1)\nTrinket\n+ 1,467 Haste\nRequires Level 90\nEquip: Your periodic damage spells have a chance to grant 7333 Intellect for 10 sec. (Approximately 1.10 procs per minute)\nSell Price:" }
entries[94522] = { ["name"] = "Talisman of Bloodlust", ["text"] = "Binds when picked up\nUnique-Equipped: Talisman of Bloodlust (1)\nTrinket\n+1,467 Agility\nRequires Level 90\nEquip: Your attacks have a chance to grant you 1538 haste for 10 sec. This effect can stack up to 5 times. (Approximately 3.50 procs per minute)\nSell Price:" }
entries[94523] = { ["name"] = "Bad Juju", ["text"] = "Binds when picked up\nUnique-Equipped: Bad Juju (1)\nTrinket\n+ 1,467 Mastery\nRequires Level 90\nEquip: When your attacks hit you have a chance to gain 7333 Agility and summon 3 Voodoo Gnomes for 10 sec. (Approximately 1.10 procs per minute)\nSell Price:" }
entries[94524] = { ["name"] = "Unerring Vision of Lei Shen", ["text"] = "Binds when picked up\nUnique-Equipped: Unerring Vision of Lei Shen (1)\nTrinket\n+1,467 Intellect\nRequires Level 90\nEquip: Your damaging spells have a chance to grant 100% critical strike chance for 4 sec. (Approximately 0.55 procs per minute)\nSell Price:" }
entries[94525] = { ["name"] = "Stolen Relic of Zuldazar", ["text"] = "Binds when picked up\nUnique-Equipped: Stolen Relic of Zuldazar (1)\nTrinket\n+1,467 Spirit\nRequires Level 90\nEquip: Your helpful spells have a chance to grant you a Blessing of Zuldazar, which stacks up to 6 times. (Approximately 2.89 procs per minute)\nUse: Consumes all Blessings of Zuldazar to shield the target, absorbing 9339 damage per Blessing consumed. Lasts 15 sec. (20 Sec Cooldown)\nSell Price:" }
entries[94526] = { ["name"] = "Spark of Zandalar", ["text"] = "Binds when picked up\nUnique-Equipped: Spark of Zandalar (1)\nTrinket\n+ 1,467 Haste\nRequires Level 90\nEquip: Your attacks have a chance to grant you a Spark of Zandalar. Once you have accumulated 10 Sparks, you will transform into a Zandalari Warrior and gain 700 Strength for 10 sec. (Approximately 11.10 procs per minute)\nSell Price:" }
entries[94527] = { ["name"] = "Ji-Kun's Rising Winds", ["text"] = "Binds when picked up\nUnique-Equipped: Ji-Kun's Rising Winds (1)\nTrinket\n+ 1,467 Expertise\nRequires Level 90\nEquip: Melee attacks which reduce you below 35% health cause you to instantly heal for 40341 . Cannot occur more than once every 30 sec. (30s cooldown)\nSell Price:" }
entries[94528] = { ["name"] = "Soul Barrier", ["text"] = "Binds when picked up\nUnique-Equipped: Soul Barrier (1)\nTrinket\n+2,201 Stamina\nRequires Level 90\nUse: Absorbs up to 11206 damage every time you take physical damage, up to a maximum of ( 11206 * 5) damage absorbed. (2 Min Cooldown)\nSell Price:" }
entries[94529] = { ["name"] = "Gaze of the Twins", ["text"] = "Binds when picked up\nUnique-Equipped: Gaze of the Twins (1)\nTrinket\n+1,467 Strength\nRequires Level 90\nEquip: Your critical attacks have a chance to grant you 2868 Critical Strike for 20 sec. This effect can stack up to 3 times. (Approximately 0.72 procs per minute)\nSell Price:" }
entries[94530] = { ["name"] = "Lightning-Imbued Chalice", ["text"] = "Binds when picked up\nUnique-Equipped: Lightning-Imbued Chalice (1)\nTrinket\n+1,467 Intellect\nRequires Level 90\nEquip: Your healing spells have a chance to grant you Infinite Power. Once you have accumulated 6 Infinite Power, you will instantly heal the most injured nearby party member for 56025 . (Approximately 5.78 procs per minute)\nSell Price:" }
entries[94531] = { ["name"] = "Cha-Ye's Essence of Brilliance", ["text"] = "Binds when picked up\nUnique-Equipped: Cha-Ye's Essence of Brilliance (1)\nTrinket\n+ 1,467 Critical Strike\nRequires Level 90\nEquip: When your spells deal critical damage, you have a chance to gain 7333 Intellect for 10 sec. (Approximately 0.85 procs per minute)\nSell Price:" }
entries[94532] = { ["name"] = "Rune of Re-Origination", ["text"] = "Binds when picked up\nUnique-Equipped: Rune of Re-Origination (1)\nTrinket\n+1,467 Agility\nRequires Level 90\nEquip: When your attacks hit you have a chance to trigger Re-Origination. Re-Origination converts the lower two values of your Critical Strike, Haste, and Mastery into twice as much of the highest of those three attributes for 10 sec. (Approximately 1.04 procs per minute, 10 sec cooldown)\nSell Price:" }
entries[94535] = { ["name"] = "Grilled Dinosaur Haunch", ["text"] = "Requires Level 90\nUse: Restores 300000 health and ( 75000 / 5 * 20) mana over 20 sec. Must remain seated while eating. If you spend at least 10 seconds eating you will become well fed and gain 200 mastery for 1 hour.\nSell Price:" }
entries[94536] = { ["name"] = "Intact Direhorn Hide", ["text"] = "Requires Level 90\nUse: Disguise yourself as a Direhorn, reducing the range at which enemies detect you for 10 min while on the Isle of Giants.\n\"Horns and everything!\"\nSell Price:" }
entries[94552] = { ["name"] = "Plans: Lightning Steel Ingot", ["text"] = "Binds when picked up\nRequires Blacksmithing (500)\nUse: Teaches you how to create Lightning Steel Ingots.\nCreate a Lightning Steel Ingot from Ghost Iron Bars. In the process, you may gain additional knowledge of Ghost Iron, and discover a Blacksmithing plan you have yet to learn. This can only be done once a day.\n\nLightning Steel Ingot\nBinds when picked up\n\"Used by Blacksmiths in the creation of powerful items.\"\nSell Price:\nRequires Ghost Iron Bar (10)" }
entries[94553] = { ["name"] = "Notes on Lightning Steel", ["text"] = "Binds when picked up\n<Right Click to Open>" }
entries[94566] = { ["name"] = "Fortuitous Coffer", ["text"] = "Binds when picked up\n<Right Click to Open>" }
entries[94567] = { ["name"] = "Plans: Thunder, Reborn", ["text"] = "Binds when picked up\nRequires Blacksmithing (500)\nUse: Teaches you how to create Thunder, Reborn.\nBy making this weapon, you will learn how to create Deep Thunder, Reborn.\n\nThunder, Reborn\nBinds when equipped\nTwo-Hand Mace\n9,462 - 14,193 Damage Speed 3.60\n(3,285 damage per second)\n+899 Agility\n+1,349 Stamina\n+ 600 Hit\n+ 600 Expertise\nDurability 100 / 100\nRequires Level 90\nSell Price:\nRequires Lightning Steel Ingot (5), Living Steel (3), Spirit of Harmony (3)" }
entries[94568] = { ["name"] = "Plans: Drakefist Hammer, Reborn", ["text"] = "Binds when picked up\nRequires Blacksmithing (500)\nUse: Teaches you how to create Drakefist Hammer, Reborn.\nBy making this weapon, you will learn how to create Dragonmaw, Reborn.\n\nDrakefist Hammer, Reborn\nBinds when equipped\nOne-Hand Mace\n1,364 - 2,534 Damage Speed 1.60\n(1,218 damage per second)\n+578 Stamina\n+385 Intellect\n+257 Spirit\n+ 257 Haste\n+ 5,152 Spell Power\nDurability 90 / 90\nRequires Level 90\nSell Price:\nRequires Lightning Steel Ingot (5), Living Steel (2), Spirit of Harmony (3)" }
entries[94569] = { ["name"] = "Plans: Lunar Crescent, Reborn", ["text"] = "Binds when picked up\nRequires Blacksmithing (500)\nUse: Teaches you how to create Lunar Crescent, Reborn.\nBy making this weapon, you will learn how to create Mooncleaver, Reborn.\n\nLunar Crescent, Reborn\nBinds when equipped\nTwo-Hand Axe\n9,462 - 14,193 Damage Speed 3.60\n(3,285 damage per second)\n+899 Strength\n+1,349 Stamina\n+ 600 Haste\n+ 600 Mastery\nDurability 100 / 100\nRequires Level 90\nSell Price:\nRequires Lightning Steel Ingot (5), Living Steel (3), Spirit of Harmony (3)" }
entries[94570] = { ["name"] = "Plans: Planar Edge, Reborn", ["text"] = "Binds when picked up\nRequires Blacksmithing (500)\nUse: Teaches you how to create Planar Edge, Reborn.\nBy making this weapon, you will learn how to create Black Planar Edge, Reborn.\n\nThe Planar Edge, Reborn\nBinds when equipped\nOne-Hand Axe\n4,434 - 8,236 Damage Speed 2.60\n(2,437 damage per second)\n+385 Strength\n+578 Stamina\n+ 257 Hit\n+ 257 Expertise\nDurability 90 / 90\nRequires Level 90\nSell Price:\nRequires Lightning Steel Ingot (5), Living Steel (2), Spirit of Harmony (3)" }
entries[94571] = { ["name"] = "Plans: Lionheart Blade, Reborn", ["text"] = "Binds when picked up\nRequires Blacksmithing (500)\nUse: Teaches you how to create Lionheart Blade, Reborn.\nBy making this weapon, you will learn how to create Lionheart Champion, Reborn.\n\nLionheart Blade, Reborn\nBinds when equipped\nTwo-Hand Sword\n9,462 - 14,193 Damage Speed 3.60\n(3,285 damage per second)\n+899 Strength\n+1,349 Stamina\n+ 600 Hit\n+ 600 Expertise\nDurability 100 / 100\nRequires Level 90\nSell Price:\nRequires Lightning Steel Ingot (5), Living Steel (3), Spirit of Harmony (3)" }
