entries[94880] = { ["name"] = "Schematic: Sky Golem", ["text"] = "Binds when picked up\nUnique\nRequires Engineering (600)\nUse: Teaches you how to create the Sky Golem.\n\nSky Golem\nMount\nRequires Level 80\nRequires Expert Riding\nUse: Teaches you how to ride the Sky Golem. This is a flying mount.\nMount a Sky Golem, allowing you to fly very fast. The claws are surprisingly delicate and herbalists can use them to pick herbs! This is a flying mount.\nSell Price:\nRequires Jard's Peculiar Energy Source (30), Living Steel (30)" }
entries[94893] = { ["name"] = "Schematic: Pierre", ["text"] = "Binds when picked up\nUnique\nRequires Engineering (600)\nUse: Teaches you how to create Pierre.\n\nPierre\nUse: Teaches you how to summon and dismiss this companion.\nRight Click to summon and dismiss Pierre. If you give him a moment to heat up, he makes an excellent cooking fire.\nRequires Jard's Peculiar Energy Source (15), Living Steel (15)" }
entries[94894] = { ["name"] = "Schematic: Advanced Refrigeration Unit", ["text"] = "Binds when picked up\nUnique\nRequires Engineering (600)\nUse: Teaches you how to create the ARU.\n\nAdvanced Refrigeration Unit\nBinds when equipped\n36 Slot Cooking Bag\nRequires Jard's Peculiar Energy Source (5), Living Steel (5)" }
